"use client";
import {useEffect,useMemo,useRef,useState} from "react";
import {createPortal} from "react-dom";
import {Activity,BriefcaseBusiness,CalendarRange,ChartNoAxesGantt,ChevronDown,ChevronRight,CircleAlert,Download,FileUp,FolderKanban,Gauge,Pencil,Plus,Printer,Trash2,Users} from "lucide-react";
import {Badge} from "@/components/ui/badge";import {Button} from "@/components/ui/button";import {Dialog,DialogContent,DialogDescription,DialogFooter,DialogHeader,DialogTitle} from "@/components/ui/dialog";import {Input} from "@/components/ui/input";import {Label} from "@/components/ui/label";import {NativeSelect,NativeSelectOption} from "@/components/ui/native-select";import {Progress} from "@/components/ui/progress";import {Tabs,TabsContent,TabsList,TabsTrigger} from "@/components/ui/tabs";import {Table,TableBody,TableCell,TableHead,TableHeader,TableRow} from "@/components/ui/table";import {Textarea} from "@/components/ui/textarea";import {AlertDialog,AlertDialogAction,AlertDialogCancel,AlertDialogContent,AlertDialogDescription,AlertDialogFooter,AlertDialogHeader,AlertDialogTitle} from "@/components/ui/alert-dialog";import {Sheet,SheetContent,SheetDescription,SheetHeader,SheetTitle} from "@/components/ui/sheet";import {Accordion,AccordionContent,AccordionItem,AccordionTrigger} from "@/components/ui/accordion";

type Employee={id:number;name:string;email:string;role:string;managerId:number|null;capacityPercent:number};type Project={id:number;code:string;name:string;color:string;description:string|null;status:string};type WorkPackage={id:number;projectId:number;code:string;name:string;description:string|null};type WorkActivity={id:number;projectId:number;workPackageId:number|null;parentActivityId:number|null;code:string|null;name:string;description:string|null;startDate:string;endDate:string;estimatedHours:number|null;status:string};type Assignment={id:number;activityId:number;employeeId:number;effortPercent:number;startDate:string;endDate:string};type Data={employees:Employee[];projects:Project[];workPackages:WorkPackage[];activities:WorkActivity[];assignments:Assignment[]};const empty:Data={employees:[],projects:[],workPackages:[],activities:[],assignments:[]};
const monthFmt=new Intl.DateTimeFormat("sv-SE",{month:"short",year:"2-digit"}),dateFmt=new Intl.DateTimeFormat("sv-SE",{day:"numeric",month:"short",year:"numeric"});const months=Array.from({length:7},(_,i)=>{const d=new Date(2026,8+i,1);return{key:`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}`,label:monthFmt.format(d).replace(".","")}});const initials=(n:string)=>n.split(" ").map(x=>x[0]).join("").slice(0,2);const esc=(v:unknown)=>`"${String(v??"").replaceAll('"','""')}"`;function parseCsv(t:string){const lines=t.replace(/^\uFEFF/,"").trim().split(/\r?\n/);if(lines.length<2)return[];const s=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?";":",";const split=(line:string)=>{const out:string[]=[];let cur="",q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&line[i+1]==='"'){cur+='"';i++}else if(c==='"')q=!q;else if(c===s&&!q){out.push(cur);cur=""}else cur+=c}out.push(cur);return out};const h=split(lines[0]).map(x=>x.trim().toLowerCase());return lines.slice(1).filter(Boolean).map(l=>Object.fromEntries(split(l).map((v,i)=>[h[i],v.trim()]))) as Array<Record<string,string>>}function download(name:string,content:string,type:string){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement("a");a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}function activeIn(a:Assignment,key:string){const [y,m]=key.split("-").map(Number),end=new Date(y,m,0).toISOString().slice(0,10);return a.startDate<=end&&a.endDate>=`${key}-01`}

export default function Home(){const[data,setData]=useState<Data>(empty),[scope,setScope]=useState("all"),[notice,setNotice]=useState(""),[error,setError]=useState(""),[dialog,setDialog]=useState<"project"|"work"|"activity"|"employee"|"assignment"|"export"|"import"|null>(null),[editing,setEditing]=useState<Project|WorkPackage|WorkActivity|null>(null),[remove,setRemove]=useState<{type:string;id:number;label:string}|null>(null),[detail,setDetail]=useState<{type:"employee"|"project"|"activity";id:number;mode:"list"|"gantt"}|null>(null);const fileRef=useRef<HTMLInputElement>(null);
 const refresh=async()=>{try{const r=await fetch("/api/data",{cache:"no-store"}),j=await r.json();if(!r.ok)throw new Error(j.error);setData(j)}catch(e){setError(e instanceof Error?e.message:"Ett fel uppstod")}};useEffect(()=>{refresh()},[]);const post=async(payload:Record<string,unknown>,message:string)=>{setError("");const r=await fetch("/api/data",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)}),j=await r.json();if(!r.ok){setError(j.error||"Kunde inte spara");return false}setData(j);setDialog(null);setEditing(null);setNotice(message);setTimeout(()=>setNotice(""),3500);return true};const submit=(e:React.FormEvent<HTMLFormElement>,action:string,message:string)=>{e.preventDefault();post({action,...Object.fromEntries(new FormData(e.currentTarget))},message)};
 const managers=data.employees.filter(e=>data.employees.some(x=>x.managerId===e.id));const visible=useMemo(()=>scope==="all"?data.employees:data.employees.filter(e=>e.managerId===Number(scope)||e.id===Number(scope)),[data.employees,scope]);const utilization=(id:number,key:string)=>data.assignments.filter(a=>a.employeeId===id&&activeIn(a,key)).reduce((s,a)=>s+a.effortPercent,0);const loads=visible.map(e=>utilization(e.id,"2026-09")),over=loads.filter((v,i)=>v>visible[i].capacityPercent).length,average=loads.length?Math.round(loads.reduce((a,b)=>a+b,0)/loads.length):0;
 const del=async()=>{if(!remove)return;const r=await fetch(`/api/data?type=${remove.type}&id=${remove.id}`,{method:"DELETE"}),j=await r.json();if(!r.ok){setError(j.error);return}setData(j);setNotice(`${remove.label} togs bort`);setRemove(null)};
 const openEdit=(kind:"project"|"work"|"activity",item:Project|WorkPackage|WorkActivity)=>{setEditing(item);setDialog(kind)};const close=()=>{setDialog(null);setEditing(null)};
 const importFile=async()=>{const f=fileRef.current?.files?.[0];if(!f){setError("Välj en fil först.");return}try{const raw=await f.text();if(f.name.toLowerCase().endsWith(".json")){const backup=JSON.parse(raw);await post({action:"restore",backup},"Säkerhetskopian återställdes")}else{const rows=parseCsv(raw);if(!rows.length)throw new Error("CSV-filen innehåller inga rader");await post({action:"import",rows},`${rows.length} rader importerades`)}}catch(e){setError(e instanceof Error?e.message:"Filen kunde inte importeras")}};
 return <main className="app-shell min-h-screen text-slate-950"><header className="app-header sticky top-0 z-30 border-b backdrop-blur-xl"><div className="mx-auto flex h-16 max-w-[1500px] items-center gap-3 px-4 sm:px-6"><div className="brand-mark"><Gauge/></div><div className="mr-auto"><div className="font-semibold">Resursplanering</div><div className="app-subtitle text-xs">Projekt, uppdrag och aktiviteter</div></div><div className="hidden items-center gap-2 lg:flex"><span className="app-subtitle text-sm">Chefsvy</span><NativeSelect className="header-select min-w-48" value={scope} onChange={e=>setScope(e.target.value)}><NativeSelectOption value="all">Alla medarbetare</NativeSelectOption>{managers.map(m=><NativeSelectOption value={m.id} key={m.id}>{m.name}s grupp</NativeSelectOption>)}</NativeSelect></div><Button className="header-action" variant="outline" onClick={()=>setDialog("export")}><Download/>Exportera</Button><Button className="header-primary" onClick={()=>setDialog("import")}><FileUp/>Importera</Button></div></header>
 <div className="mx-auto max-w-[1500px] px-4 py-6 sm:px-6 lg:py-8">{(notice||error)&&<div className={`mb-4 rounded-xl border px-4 py-3 text-sm ${error?"border-red-200 bg-red-50 text-red-800":"border-emerald-200 bg-emerald-50 text-emerald-800"}`}>{error||notice}</div>}<div className="mb-6 flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="eyebrow">Planeringsperiod · Sep 2026–Mar 2027</p><h1 className="text-3xl font-semibold tracking-[-.035em] sm:text-4xl">Planera från projekt till underaktivitet</h1><p className="mt-2 max-w-2xl text-slate-600">Bygg en tydlig struktur, bemanna arbetet och exportera valda delar eller hela databasen.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>setDialog("employee")}><Plus/>Medarbetare</Button><Button variant="outline" onClick={()=>setDialog("project")}><Plus/>Projekt</Button><Button variant="outline" onClick={()=>setDialog("work")}><Plus/>Uppdrag</Button><Button variant="outline" onClick={()=>setDialog("activity")}><Plus/>Aktivitet</Button><Button onClick={()=>setDialog("assignment")}><Plus/>Bemanna</Button></div></div>
 <section className="mb-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={<Users/>} label="Medarbetare" value={visible.length} hint={scope==="all"?"hela organisationen":"vald chefsgrupp"}/><Metric icon={<BriefcaseBusiness/>} label="Projekt och uppdrag" value={`${data.projects.length} / ${data.workPackages.length}`} hint={`${data.activities.length} aktiviteter`}/><Metric icon={<Activity/>} label="Genomsnittlig beläggning" value={`${average}%`} hint="innevarande månad"/><Metric icon={<CircleAlert/>} label="Överbelagda" value={over} hint={over?"behöver omplaneras":"inga konflikter"} alert={over>0}/></section>
 <Tabs defaultValue="load" className="gap-4"><TabsList variant="line" className="main-tabs mb-1 h-12 gap-1 overflow-x-auto"><TabsTrigger value="load"><Gauge/>Beläggning</TabsTrigger><TabsTrigger value="structure"><FolderKanban/>Projektstruktur</TabsTrigger><TabsTrigger value="activities"><CalendarRange/>Aktiviteter</TabsTrigger><TabsTrigger value="employees"><Users/>Medarbetare</TabsTrigger></TabsList>
 <TabsContent value="load"><LoadPanel employees={visible} months={months} utilization={utilization} onSelect={id=>setDetail({type:"employee",id,mode:"list"})}/></TabsContent>
 <TabsContent value="structure"><div className="grid gap-4 xl:grid-cols-2">{data.projects.map(p=><ProjectCard key={p.id} project={p} work={data.workPackages.filter(w=>w.projectId===p.id)} activities={data.activities.filter(a=>a.projectId===p.id)} onSelect={()=>setDetail({type:"project",id:p.id,mode:"list"})} onEdit={openEdit} onRemove={setRemove}/>)}</div></TabsContent>
 <TabsContent value="activities"><ActivityTable data={data} onSelect={id=>setDetail({type:"activity",id,mode:"list"})} onPersonSelect={id=>setDetail({type:"employee",id,mode:"list"})} onEdit={a=>openEdit("activity",a)} onRemove={setRemove}/></TabsContent>
 <TabsContent value="employees"><EmployeeGrid data={data} employees={visible} onSelect={id=>setDetail({type:"employee",id,mode:"list"})} onRemove={setRemove}/></TabsContent></Tabs></div>
 <ProjectDialog open={dialog==="project"} close={close} item={editing as Project|null} onSubmit={e=>submit(e,editing?"updateProject":"project",editing?"Projektet uppdaterades":"Projektet skapades")}/><WorkDialog open={dialog==="work"} close={close} item={editing as WorkPackage|null} projects={data.projects} onSubmit={e=>submit(e,editing?"updateWorkPackage":"workPackage",editing?"Uppdraget uppdaterades":"Uppdraget skapades")}/><ActivityDialog open={dialog==="activity"} close={close} item={editing as WorkActivity|null} data={data} onSubmit={e=>submit(e,editing?"updateActivity":"activity",editing?"Aktiviteten uppdaterades":"Aktiviteten skapades")}/><EmployeeDialog open={dialog==="employee"} close={close} employees={data.employees} onSubmit={e=>submit(e,"employee","Medarbetaren skapades")}/><AssignmentDialog open={dialog==="assignment"} close={close} data={data} onSubmit={e=>submit(e,"assignment","Bemanningen sparades")}/><ExportDialog open={dialog==="export"} close={close} data={data}/><ImportDialog open={dialog==="import"} close={close} fileRef={fileRef} run={importFile}/>
 <DetailSheet detail={detail} data={data} close={()=>setDetail(null)} setMode={mode=>detail&&setDetail({...detail,mode})} onSelect={setDetail}/><AlertDialog open={!!remove} onOpenChange={o=>!o&&setRemove(null)}><AlertDialogContent><AlertDialogHeader><AlertDialogTitle>Ta bort {remove?.label}?</AlertDialogTitle><AlertDialogDescription>{remove?.type==="employee"?"Medarbetarens bemanning tas bort. Projekt och aktiviteter behålls, och eventuella underställda blir utan ansvarig chef tills en ny chef väljs.":"Underliggande aktiviteter och bemanning tas också bort."} Åtgärden kan inte ångras annat än genom att återställa en säkerhetskopia.</AlertDialogDescription></AlertDialogHeader><AlertDialogFooter><AlertDialogCancel>Avbryt</AlertDialogCancel><AlertDialogAction onClick={del} className="bg-red-600 hover:bg-red-700">Ta bort</AlertDialogAction></AlertDialogFooter></AlertDialogContent></AlertDialog></main>}

function Metric({icon,label,value,hint,alert=false}:{icon:React.ReactNode;label:string;value:string|number;hint:string;alert?:boolean}){return <article className={`metric ${alert?"metric-alert":""}`}><div className="metric-icon">{icon}</div><div><p>{label}</p><strong>{value}</strong><span>{hint}</span></div></article>}
function Avatar({name}:{name:string}){return <div className="avatar">{initials(name)}</div>}function Field({label,children}:{label:string;children:React.ReactNode}){return <div className="grid gap-2"><Label>{label}</Label>{children}</div>}function Actions({edit,remove}:{edit:()=>void;remove:()=>void}){return <div className="flex justify-end gap-1"><Button size="icon-sm" variant="ghost" aria-label="Redigera" onClick={edit}><Pencil/></Button><Button size="icon-sm" variant="ghost" className="text-red-600" aria-label="Ta bort" onClick={remove}><Trash2/></Button></div>}
function LoadPanel({employees,months,utilization,onSelect}:{employees:Employee[];months:{key:string;label:string}[];utilization:(id:number,key:string)=>number;onSelect:(id:number)=>void}){return <section className="panel overflow-hidden"><div className="panel-head"><div><h2>Beläggning per månad</h2><p>Klicka på en medarbetare för projekt, aktiviteter och personligt Gantt-schema.</p></div><div className="legend"><span><i className="bg-emerald-500"/>Under 80%</span><span><i className="bg-amber-500"/>80–100%</span><span><i className="bg-red-500"/>Över kapacitet</span></div></div><div className="overflow-x-auto"><div className="capacity-grid min-w-[980px]"><div className="capacity-header sticky left-0 z-10 bg-slate-50">Medarbetare</div>{months.map(m=><div className="capacity-header" key={m.key}>{m.label}</div>)}{employees.map(e=><div className="contents" key={e.id}><button type="button" onClick={()=>onSelect(e.id)} className="person-cell sticky left-0 z-10 bg-white text-left transition hover:bg-blue-50"><Avatar name={e.name}/><div className="min-w-0"><strong className="text-blue-800 hover:underline">{e.name}</strong><span>{e.role} · {e.capacityPercent}% kap.</span></div><ChevronRight className="ml-auto h-4 w-4 text-slate-400"/></button>{months.map(m=>{const v=utilization(e.id,m.key),ratio=v/e.capacityPercent;return <div className="load-cell" key={m.key}><div className={`load-pill ${ratio>1?"load-over":ratio>=.8?"load-high":"load-ok"}`}><span>{v}%</span><Progress value={Math.min(100,ratio*100)}/></div></div>})}</div>)}</div></div></section>}
function ProjectCard({project,work,activities,onSelect,onEdit,onRemove}:{project:Project;work:WorkPackage[];activities:WorkActivity[];onSelect:()=>void;onEdit:(k:"project"|"work",i:Project|WorkPackage)=>void;onRemove:(x:{type:string;id:number;label:string})=>void}){return <article className="panel overflow-hidden"><div className="flex items-start gap-3 p-5"><span className="mt-1 h-11 w-1.5 rounded-full" style={{background:project.color}}/><button type="button" onClick={onSelect} className="min-w-0 flex-1 text-left"><div className="flex items-center gap-2"><span className="text-xs font-bold text-blue-700">{project.code}</span><Badge variant={project.status==="Aktivt"?"default":"secondary"}>{project.status}</Badge></div><h3 className="mt-1 text-lg font-semibold text-blue-950 hover:underline">{project.name}</h3><p className="mt-1 text-sm text-slate-500">{project.description||`${activities.length} aktiviteter`}</p></button><Button size="sm" variant="secondary" onClick={onSelect}><ChartNoAxesGantt/>Visa</Button><Actions edit={()=>onEdit("project",project)} remove={()=>onRemove({type:"project",id:project.id,label:`projektet ${project.name}`})}/></div><div className="border-t bg-slate-50/70 p-3"><div className="mb-2 px-2 text-xs font-bold uppercase tracking-wider text-slate-500">Uppdrag</div>{work.length?work.map(w=><div key={w.id} className="mb-2 flex items-center gap-3 rounded-xl border bg-white p-3"><div className="grid h-8 w-8 place-items-center rounded-lg bg-blue-50 text-blue-700"><FolderKanban className="h-4 w-4"/></div><div className="min-w-0 flex-1"><div className="text-sm font-medium">{w.code} · {w.name}</div><div className="text-xs text-slate-500">{activities.filter(a=>a.workPackageId===w.id).length} aktiviteter</div></div><Actions edit={()=>onEdit("work",w)} remove={()=>onRemove({type:"workPackage",id:w.id,label:`uppdraget ${w.name}`})}/></div>):<p className="px-2 pb-2 text-sm text-slate-400">Inga uppdrag skapade.</p>}</div></article>}
function ActivityTable({data,onSelect,onPersonSelect,onEdit,onRemove}:{data:Data;onSelect:(id:number)=>void;onPersonSelect:(id:number)=>void;onEdit:(a:WorkActivity)=>void;onRemove:(x:{type:string;id:number;label:string})=>void}){
 const[projectId,setProjectId]=useState("all"),[workId,setWorkId]=useState("all"),[view,setView]=useState<"list"|"gantt">("list");
 const work=data.workPackages.filter(w=>projectId==="all"||w.projectId===Number(projectId));
 const filtered=data.activities.filter(a=>(projectId==="all"||a.projectId===Number(projectId))&&(workId==="all"||a.workPackageId===Number(workId)));
 const sorted=[...filtered].sort((a,b)=>a.projectId-b.projectId||Number(!!a.parentActivityId)-Number(!!b.parentActivityId)||a.startDate.localeCompare(b.startDate));
 return <section className="panel overflow-hidden"><div className="panel-head flex-col gap-4 xl:flex-row xl:items-end"><div className="mr-auto"><h2>Aktiviteter och underaktiviteter</h2><p>{filtered.length} av {data.activities.length} aktiviteter visas. Välj Alla projekt för en ofiltrerad vy.</p></div><div className="grid w-full gap-3 sm:grid-cols-2 xl:w-auto xl:grid-cols-[15rem_15rem_auto]"><Field label="Projekt"><NativeSelect className="w-full" value={projectId} onChange={e=>{setProjectId(e.target.value);setWorkId("all")}}><NativeSelectOption value="all">Alla projekt</NativeSelectOption>{data.projects.map(p=><NativeSelectOption key={p.id} value={p.id}>{p.code} · {p.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Uppdrag"><NativeSelect className="w-full" value={workId} onChange={e=>setWorkId(e.target.value)} disabled={projectId==="all"}><NativeSelectOption value="all">Alla uppdrag i projektet</NativeSelectOption>{work.map(w=><NativeSelectOption key={w.id} value={w.id}>{w.code} · {w.name}</NativeSelectOption>)}</NativeSelect></Field><div className="flex items-end gap-1"><Button variant={view==="list"?"default":"outline"} onClick={()=>setView("list")}><CalendarRange/>Lista</Button><Button variant={view==="gantt"?"default":"outline"} onClick={()=>setView("gantt")}><ChartNoAxesGantt/>Gantt</Button></div></div></div>{view==="gantt"?<div className="overflow-x-auto border-t bg-slate-50/40 p-3 sm:p-5"><div className="min-w-[900px]"><GanttView items={activitySelectionGantt(sorted,data)} empty="Inga aktiviteter matchar filtret."/></div></div>:<div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>Aktivitet</TableHead><TableHead>Projekt / uppdrag</TableHead><TableHead>Period</TableHead><TableHead>Beläggning</TableHead><TableHead>Bemanning</TableHead><TableHead/></TableRow></TableHeader><TableBody>{sorted.map(a=>{const p=data.projects.find(x=>x.id===a.projectId),w=data.workPackages.find(x=>x.id===a.workPackageId),ass=data.assignments.filter(x=>x.activityId===a.id),load=ass.reduce((s,x)=>s+x.effortPercent,0);return <TableRow key={a.id}><TableCell><button type="button" onClick={()=>onSelect(a.id)} className={`flex items-center gap-2 text-left ${a.parentActivityId?"pl-7":""}`}>{a.parentActivityId?<ChevronRight className="h-4 w-4 text-slate-400"/>:<ChevronDown className="h-4 w-4 text-blue-600"/>}<div><div className="font-medium text-blue-900 hover:underline">{a.code&&<span className="mr-2 text-xs text-blue-700">{a.code}</span>}{a.name}</div>{a.description&&<div className="max-w-72 truncate text-xs text-slate-500">{a.description}</div>}</div></button></TableCell><TableCell><button type="button" onClick={()=>onSelect(a.id)} className="text-left"><div className="text-sm">{p?.code}</div><div className="text-xs text-slate-500">{w?.name||"Direkt i projekt"}</div></button></TableCell><TableCell>{dateFmt.format(new Date(a.startDate))} – {dateFmt.format(new Date(a.endDate))}</TableCell><TableCell><Badge variant={load>100?"destructive":"outline"}>{load}% totalt</Badge></TableCell><TableCell><div className="flex -space-x-2">{ass.map(x=>{const e=data.employees.find(y=>y.id===x.employeeId);return <button type="button" onClick={()=>e&&onPersonSelect(e.id)} className="mini-avatar" title={`${e?.name}: ${x.effortPercent}%`} key={x.id}>{initials(e?.name||"")}</button>})}{!ass.length&&<span className="text-sm text-slate-400">Ej bemannad</span>}</div></TableCell><TableCell><Actions edit={()=>onEdit(a)} remove={()=>onRemove({type:"activity",id:a.id,label:`aktiviteten ${a.name}`})}/></TableCell></TableRow>})}{!sorted.length&&<TableRow><TableCell colSpan={6} className="h-28 text-center text-slate-400">Inga aktiviteter matchar filtret.</TableCell></TableRow>}</TableBody></Table></div>}</section>
}
function EmployeeGrid({data,employees,onSelect,onRemove}:{data:Data;employees:Employee[];onSelect:(id:number)=>void;onRemove:(x:{type:string;id:number;label:string})=>void}){return <section className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{employees.map(e=>{const manager=data.employees.find(x=>x.id===e.managerId),ass=data.assignments.filter(x=>x.employeeId===e.id);return <article className="employee-card transition hover:-translate-y-0.5 hover:border-blue-300 hover:shadow-md" key={e.id}><div className="flex items-start gap-3"><button type="button" onClick={()=>onSelect(e.id)} className="flex min-w-0 flex-1 items-start gap-3 text-left"><Avatar name={e.name}/><div className="min-w-0"><h3 className="truncate text-blue-950 hover:underline">{e.name}</h3><p>{e.role}</p></div><Badge variant="outline" className="ml-auto">{e.capacityPercent}% kap.</Badge></button><Button size="icon-sm" variant="ghost" className="shrink-0 text-red-600 hover:bg-red-50 hover:text-red-700" aria-label={`Ta bort ${e.name}`} title={`Ta bort ${e.name}`} onClick={()=>onRemove({type:"employee",id:e.id,label:`medarbetaren ${e.name}`})}><Trash2/></Button></div><button type="button" onClick={()=>onSelect(e.id)} className="mt-5 block w-full border-t pt-4 text-left text-sm"><div className="flex justify-between text-slate-500"><span>Ansvarig chef</span><strong className="text-slate-800">{manager?.name||"–"}</strong></div><div className="mt-2 flex justify-between text-slate-500"><span>Aktiviteter</span><strong className="text-slate-800">{ass.length}</strong></div><div className="mt-4 flex items-center justify-end gap-1 font-medium text-blue-700"><ChartNoAxesGantt className="h-4 w-4"/>Visa planering</div></button></article>})}</section>}

type Detail={type:"employee"|"project"|"activity";id:number;mode:"list"|"gantt"};type GanttItem={id:string;group:string;label:string;sub:string;start:string;end:string;color:string;effort?:number};type LoadPoint={key:string;label:string;value:number};
