type PrintPeriod="1w"|"2w"|"3w"|"4w"|"2m"|"3m"|"4m"|"5m"|"6m"|"all";type PlanningRow={id:string;project:string;work:string;activity:string;description:string;people:string;effort:string;start:string;end:string};
