function periodEnd(start:string,period:PrintPeriod){const d=new Date(`${start}T00:00:00Z`);if(period.endsWith("w"))d.setUTCDate(d.getUTCDate()+Number(period[0])*7-1);else if(period.endsWith("m")){d.setUTCMonth(d.getUTCMonth()+Number(period[0]));d.setUTCDate(d.getUTCDate()-1)}return d.toISOString().slice(0,10)}
