function timelineSegments(start:string,end:string):TimelineSegment[]{const from=new Date(`${start}T00:00:00Z`),to=new Date(`${end}T00:00:00Z`),days=Math.max(1,Math.ceil((to.getTime()-from.getTime())/86400000)+1),daily=days<=35,dayLetters=["s","m","t","o","t","f","l"],monthName=new Intl.DateTimeFormat("sv-SE",{month:"long"});if(daily)return Array.from({length:days},(_,i)=>{const date=new Date(from.getTime()+i*86400000),iso=date.toISOString().slice(0,10);return{key:iso,label:dayLetters[date.getUTCDay()],start:iso,end:iso}});const segments:TimelineSegment[]=[];for(let cursor=new Date(from);cursor<=to;){const nextMonth=new Date(Date.UTC(cursor.getUTCFullYear(),cursor.getUTCMonth()+1,1)),segmentEnd=new Date(Math.min(to.getTime(),nextMonth.getTime()-86400000)),iso=cursor.toISOString().slice(0,10);segments.push({key:iso,label:monthName.format(cursor),start:iso,end:segmentEnd.toISOString().slice(0,10)});cursor=nextMonth}return segments}
function timelineColumns(segments:TimelineSegment[]){return segments.map(segment=>`${Math.max(1,(new Date(`${segment.end}T00:00:00Z`).getTime()-new Date(`${segment.start}T00:00:00Z`).getTime())/86400000+1)}fr`).join(" ")}
function timelineWeekGroups(segments:TimelineSegment[]){return segments.reduce<{key:string;label:string;count:number}[]>((groups,segment)=>{const date=new Date(`${segment.start}T00:00:00Z`),label=`v. ${isoWeek(date)}`,last=groups.at(-1);if(last?.label===label)last.count+=1;else groups.push({key:segment.start,label,count:1});return groups},[])}
