function employeeGantt(e:Employee,d:Data):GanttItem[]{return d.assignments.filter(s=>s.employeeId===e.id).flatMap(s=>{const a=d.activities.find(x=>x.id===s.activityId),p=d.projects.find(x=>x.id===a?.projectId),w=d.workPackages.find(x=>x.id===a?.workPackageId);return a&&p?[{id:String(s.id),group:`${p.code} · ${p.name}`,label:`${a.parentActivityId?"↳ ":""}${a.code?`${a.code} · `:""}${a.name}`,sub:`${w?`${w.code} · ${w.name} · `:""}${s.effortPercent}% insats`,start:a.startDate,end:a.endDate,color:p.color,effort:s.effortPercent}]:[]}).sort((a,b)=>a.group.localeCompare(b.group,"sv")||a.start.localeCompare(b.start)||a.label.localeCompare(b.label,"sv"))}
