function projectGantt(p:Project,d:Data):GanttItem[]{return d.activities.filter(a=>a.projectId===p.id).flatMap(a=>{const w=d.workPackages.find(x=>x.id===a.workPackageId),ass=d.assignments.filter(s=>s.activityId===a.id),group=w?`${w.code} · ${w.name}`:"Direkt i projektet",label=`${a.parentActivityId?"↳ ":""}${a.code?`${a.code} · `:""}${a.name}`;if(!ass.length)return[{id:`${a.id}-empty`,group,label,sub:"Ej bemannad",start:a.startDate,end:a.endDate,color:p.color}];return ass.map(s=>{const e=d.employees.find(x=>x.id===s.employeeId);return{id:`${a.id}-${s.id}`,group,label,sub:`${e?.name||"Okänd resurs"} · ${s.effortPercent}% insats`,start:a.startDate,end:a.endDate,color:p.color,effort:s.effortPercent}})}).sort((a,b)=>a.group.localeCompare(b.group,"sv")||a.start.localeCompare(b.start)||a.label.localeCompare(b.label,"sv")||a.sub.localeCompare(b.sub,"sv"))}
function activityGantt(a:WorkActivity,d:Data):GanttItem[]{const p=d.projects.find(x=>x.id===a.projectId),group=`${a.code?`${a.code} · `:""}${a.name}`;return d.assignments.filter(s=>s.activityId===a.id).map(s=>{const e=d.employees.find(x=>x.id===s.employeeId);return{id:String(s.id),group,label:e?.name||"Resurs",sub:`${e?.role||"Medarbetare"} · ${s.effortPercent}% insats`,start:a.startDate,end:a.endDate,color:p?.color||"#2563eb",effort:s.effortPercent}}).sort((a,b)=>a.label.localeCompare(b.label,"sv"))}
function GanttView({items,empty,load,segments:givenSegments,rangeStart="2026-09-01",rangeEnd="2027-03-31"}:{items:GanttItem[];empty:string;load?:LoadPoint[];segments?:TimelineSegment[];rangeStart?:string;rangeEnd?:string}){const start=new Date(`${rangeStart}T00:00:00Z`),endExclusive=new Date(`${rangeEnd}T00:00:00Z`).getTime()+86400000,span=Math.max(86400000,endExclusive-start.getTime()),segments=givenSegments||timelineSegments(rangeStart,rangeEnd),daily=segments.every(segment=>segment.start===segment.end),posStart=(date:string)=>Math.max(0,Math.min(100,(new Date(`${date}T00:00:00Z`).getTime()-start.getTime())/span*100)),posEnd=(date:string)=>Math.max(0,Math.min(100,(new Date(`${date}T00:00:00Z`).getTime()+86400000-start.getTime())/span*100)),groups=[...new Set(items.map(i=>i.group))],columns=timelineColumns(segments);return <section className="gantt-card">{load&&<div className="gantt-load"><div className="gantt-load-label"><strong>Beläggning</strong><span>Grön &lt;85% · Gul 85–100% · Röd &gt;100%</span></div><div className={`gantt-load-scale${daily?" is-daily":""}`} style={{gridTemplateColumns:columns}}>{load.map(point=><div key={point.key} title={`${point.label}: ${point.value}% beläggning`} className={point.value>100?"load-red":point.value>=85?"load-yellow":"load-green"}><strong>{point.value}%</strong><span>{point.label}</span></div>)}</div></div>}<div className={`gantt-head${daily?" is-daily":""}`}><div>Aktivitet / resurs</div><TimelineScale segments={segments} className="gantt-head-scale"/></div>{groups.map(group=><div key={group}><div className="gantt-group"><FolderKanban/><span>{group}</span><Badge variant="secondary">{items.filter(i=>i.group===group).length} rader</Badge></div>{items.filter(i=>i.group===group).map(i=>{const left=posStart(i.start),right=posEnd(i.end),width=Math.max(1.5,right-left),continuesLeft=i.start<rangeStart,continuesRight=i.end>rangeEnd;return <div className="gantt-row" key={i.id}><div className="gantt-label"><strong>{i.label}</strong><span>{i.sub}</span></div><div className="gantt-track"><div className="gantt-grid" style={{gridTemplateColumns:columns}}>{segments.map(segment=><i key={segment.key}/>)}</div><div className={`gantt-bar${continuesLeft?" continues-left":""}${continuesRight?" continues-right":""}`} title={`${i.label} · ${i.sub}: ${i.start} – ${i.end}${continuesLeft||continuesRight?" · fortsätter utanför visningsperioden":""}`} style={{left:`${left}%`,width:`${width}%`,background:i.color}}><span>{continuesLeft&&"‹ "}{i.effort?`${i.effort}%`:""}{continuesRight&&" ›"}</span></div></div></div>})}</div>)}{!items.length&&<div className="p-10 text-center text-sm text-slate-400">{empty}</div>}</section>}

