function ExportDialog({open,close,data}:{open:boolean;close:()=>void;data:Data}){const[kind,setKind]=useState("activities"),[project,setProject]=useState("all"),[work,setWork]=useState("all"),[person,setPerson]=useState("all"),[group,setGroup]=useState("all");const run=()=>{if(kind==="backup"){download(`resursplanering-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify({version:1,exportedAt:new Date().toISOString(),data},null,2),"application/json");close();return}if(kind==="people"){const ids=group==="all"?null:new Set(data.employees.filter(e=>e.managerId===Number(group)||e.id===Number(group)).map(e=>e.id));const people=data.employees.filter(e=>(person==="all"||e.id===Number(person))&&(!ids||ids.has(e.id)));const h=["record_type","name","email","role","manager_email","capacity_percent"],rows=people.map(e=>["person",e.name,e.email,e.role,data.employees.find(m=>m.id===e.managerId)?.email||"",e.capacityPercent]);download("medarbetare.csv",[h,...rows].map(r=>r.map(esc).join(";")).join("\n"),"text/csv;charset=utf-8");close();return}let acts=data.activities.filter(a=>(project==="all"||a.projectId===Number(project))&&(work==="all"||a.workPackageId===Number(work)));const groupIds=group==="all"?null:new Set(data.employees.filter(e=>e.managerId===Number(group)||e.id===Number(group)).map(e=>e.id));const h=["record_type","project_code","project_name","project_description","project_status","work_package_code","work_package_name","work_package_description","activity_code","activity","parent_activity_code","description","start_date","end_date","estimated_hours","status","employee_email","employee_name","effort_percent"];const rows:unknown[][]=[];for(const a of acts){const p=data.projects.find(x=>x.id===a.projectId),w=data.workPackages.find(x=>x.id===a.workPackageId),parent=data.activities.find(x=>x.id===a.parentActivityId);let ass=data.assignments.filter(x=>x.activityId===a.id&&(person==="all"||x.employeeId===Number(person))&&(!groupIds||groupIds.has(x.employeeId)));if((person!=="all"||groupIds)&&!ass.length)continue;if(!ass.length)ass=[{id:0,activityId:a.id,employeeId:0,effortPercent:0,startDate:a.startDate,endDate:a.endDate}];for(const s of ass){const e=data.employees.find(x=>x.id===s.employeeId);rows.push(["activity",p?.code,p?.name,p?.description,p?.status,w?.code,w?.name,w?.description,a.code,a.name,parent?.code,a.description,a.startDate,a.endDate,a.estimatedHours,a.status,e?.email,e?.name,s.id?s.effortPercent:""])}}download("aktiviteter.csv",[h,...rows].map(r=>r.map(esc).join(";")).join("\n"),"text/csv;charset=utf-8");close()};return <Dialog open={open} onOpenChange={o=>!o&&close()}><DialogContent className="sm:max-w-xl"><DialogHeader><DialogTitle>Exportera data</DialogTitle><DialogDescription>CSV är anpassat för Excel. JSON bevarar hela databasen som säkerhetskopia.</DialogDescription></DialogHeader><Field label="Vad vill du exportera?"><NativeSelect className="w-full" value={kind} onChange={e=>setKind(e.target.value)}><NativeSelectOption value="activities">Aktiviteter och underaktiviteter</NativeSelectOption><NativeSelectOption value="people">Medarbetare</NativeSelectOption><NativeSelectOption value="backup">Hela databasen – säkerhetskopia</NativeSelectOption></NativeSelect></Field>{kind==="activities"&&<div className="grid gap-4 sm:grid-cols-2"><Field label="Projekt"><NativeSelect className="w-full" value={project} onChange={e=>setProject(e.target.value)}><NativeSelectOption value="all">Alla projekt</NativeSelectOption>{data.projects.map(p=><NativeSelectOption key={p.id} value={p.id}>{p.code} · {p.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Uppdrag"><NativeSelect className="w-full" value={work} onChange={e=>setWork(e.target.value)}><NativeSelectOption value="all">Alla uppdrag</NativeSelectOption>{data.workPackages.filter(w=>project==="all"||w.projectId===Number(project)).map(w=><NativeSelectOption key={w.id} value={w.id}>{w.code} · {w.name}</NativeSelectOption>)}</NativeSelect></Field></div>}{kind!=="backup"&&<div className="grid gap-4 sm:grid-cols-2"><Field label="Person"><NativeSelect className="w-full" value={person} onChange={e=>setPerson(e.target.value)}><NativeSelectOption value="all">Alla personer</NativeSelectOption>{data.employees.map(e=><NativeSelectOption key={e.id} value={e.id}>{e.name}</NativeSelectOption>)}</NativeSelect></Field><Field label="Chefsgrupp"><NativeSelect className="w-full" value={group} onChange={e=>setGroup(e.target.value)}><NativeSelectOption value="all">Alla grupper</NativeSelectOption>{data.employees.filter(e=>data.employees.some(x=>x.managerId===e.id)).map(e=><NativeSelectOption key={e.id} value={e.id}>{e.name}s grupp</NativeSelectOption>)}</NativeSelect></Field></div>}<div className="rounded-xl bg-blue-50 p-3 text-sm text-blue-800">{kind==="backup"?"Säkerhetskopian innehåller projekt, uppdrag, aktiviteter, personer och all bemanning.":"Varje rad kan redigeras i Excel och importeras tillbaka till verktyget."}</div><DialogFooter><Button variant="outline" onClick={close}>Avbryt</Button><Button onClick={run}><Download/>Exportera</Button></DialogFooter></DialogContent></Dialog>}
function ImportDialog({open,close,fileRef,run}:{open:boolean;close:()=>void;fileRef:React.RefObject<HTMLInputElement|null>;run:()=>void}){return <Dialog open={open} onOpenChange={o=>!o&&close()}><DialogContent><DialogHeader><DialogTitle>Importera CSV eller säkerhetskopia</DialogTitle><DialogDescription>CSV lägger till eller uppdaterar poster. En JSON-säkerhetskopia ersätter hela databasen.</DialogDescription></DialogHeader><Field label="Fil"><Input ref={fileRef} type="file" accept=".csv,.json,text/csv,application/json"/></Field><div className="csv-example">CSV: project_code; project_name; work_package_code; activity_code; activity; parent_activity_code; start_date; end_date; employee_email; effort_percent</div><div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-sm text-amber-900"><strong>Observera:</strong> Import av JSON återställer databasen exakt som den såg ut när säkerhetskopian skapades.</div><DialogFooter><Button variant="outline" onClick={close}>Avbryt</Button><Button onClick={run}><FileUp/>Importera fil</Button></DialogFooter></DialogContent></Dialog>}
